        codePoint = b1 & 0x0F;
        bytesNeeded = 3;
    } else if ((b1 & 0xF8) == 0xF0) {
        codePoint = b1 & 0x07;
        bytesNeeded = 4;
    } else {
        // Invalid first byte
        codePoint = 0xFFFD;
        bytesNeeded = 1;
    }

    for (int j = 1; j < bytesNeeded; j++) {
        int b = dup.get() & 0xFF;
        if ((b & 0xC0) != 0x80) {
            // Invalid continuation byte
            codePoint = 0xFFFD;
            bytesNeeded = j + 1;
            break;
