private TreeNode<T> rotateRight(TreeNode<T> node){
    TreeNode<T> newRoot = node.left;
    node.left = newRoot.right;
    if (newRoot.right != null) {
        newRoot.right.parent = node;
    }
    newRoot.right = node;
    newRoot.parent = node.parent;
    node.parent = newRoot;
    if (newRoot.parent != null) {
        if (newRoot.parent.left == node) {
            newRoot.parent.left = newRoot;
        } else {
            newRoot.parent.right = newRoot;
        }
    }
    return newRoot;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.getLeft() == null) {
        return node;
    }
    TreeNode<T> left = node.getLeft();
    node.setLeft(left.getRight());
    if (left.getRight() != null) {
        left.getRight().setParent(node);
    }
    left.setRight(node);
    left.setParent(node.getParent());
    node.setParent(left);
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> left = node.left;
    TreeNode<T> rightOfLeft = left.right;

    // Perform rotation
    left.right = node;
    node.left = rightOfLeft;

    if (rightOfLeft != null) {
        rightOfLeft.parent = node;
    }

    TreeNode<T> parent = node.parent;
    left.parent = parent;

    if (parent == null) {
        // node was root; after rotation left becomes new root
    } else if (parent.left == node) {
        parent.left = left;
    } else if (parent.right == node) {
        parent.right = left;
    }

    node.parent = left;

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.getLeft();
    if (leftChild == null) {
        return node;
    }
    TreeNode<T> rightOfLeft = leftChild.getRight();
    leftChild.setRight(node);
    node.setLeft(rightOfLeft);
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) return null;
    TreeNode<T> left = node.left;
    if (left == null) return node;
    node.left = left.right;
    if (left.right != null) left.right.parent = node;
    left.right = node;
    left.parent = node.parent;
    node.parent = left;
    if (left.parent != null) {
        if (left.parent.left == node) left.parent.left = left;
        else if (left.parent.right == node) left.parent.right = left;
    }
    return left;
}

