        throw new NullPointerException("file");
    }
    if (file.isDirectory()) {
        File[] contents = file.listFiles();
        if (contents != null) {
            for (File sub : contents) {
                forceDeleteOnExit(sub);
            }
        }
    }
    file.deleteOnExit();
}

void function ( File arg0 ) throws IOException {
    if (arg0 == null) {
        throw new NullPointerException();
    }
    Runtime.getRuntime().addShutdownHook(new Thread() {
        @Override
        public void run() {
            try {
                java.util.Deque<File> stack = new java.util.ArrayDeque<>();
                stack.push(arg0);
                while (!stack.isEmpty()) {
                    File curr = stack.pop();
                    File[] files = curr.listFiles();
                    if (files != null) {
                        for (File f : files) {
                            if (f.isDirectory()) {
                                stack.push(f);
                            } else {
                                f.delete();
                            }
                        }
                    }
                    curr.delete();
                }
            } catch (Exception ignored) {
            }
        }
    });
}

