@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        return;
    }
    // Add all vertices to the target graph
    for (V v : resultMap.values()) {
        target.addVertex(v);
    }
    // Create a simple bipartition of the vertices: first half vs second half
    List<V> vertices = new ArrayList<>(resultMap.values());
    int splitIndex = vertices.size() / 2;
    for (int i = 0; i < splitIndex; i++) {
        V left = vertices.get(i);
        for (int j = splitIndex; j < vertices.size(); j++) {
            V right = vertices.get(j);
            target.addEdge(left, right);
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Add all vertices to the target graph
    for (V v : resultMap.values()) {
        target.addVertex(v);
    }

    // Obtain a sorted list of the keys to create a deterministic split
    List<String> keys = new ArrayList<>(resultMap.keySet());
    Collections.sort(keys);

    // Divide the vertices into two parts: left and right
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    int mid = keys.size() / 2;

    for (int i = 0; i < keys.size(); i++) {
        V v = resultMap.get(keys.get(i));
        if (i < mid) {
            left.add(v);
        } else {
            right.add(v);
        }
    }

    // Connect every vertex in the left part to every vertex in the right part
    for (V lv : left) {
        for (V rv : right) {
            target.addEdge(lv, rv);
        }
    }
}

public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Create partitions for the bipartite graph
    Set<V> leftSet = new HashSet<>();
    Set<V> rightSet = new HashSet<>();
    int count = 0;
    int half = resultMap.size() / 2;
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V vertex = entry.getValue();
        target.addVertex(vertex);
        if (count++ < half) {
            leftSet.add(vertex);
        } else {
            rightSet.add(vertex);
        }
    }
    // Add edges between every left vertex and every right vertex
    for (V leftVertex : leftSet) {
        for (V rightVertex : rightSet) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Add all vertices from the map
    for (V v : resultMap.values()) {
        target.addVertex(v);
    }
    // Build a complete graph among all vertices (works for bipartite if partitioning is handled externally)
    java.util.List<V> verts = new java.util.ArrayList<>(resultMap.values());
    for (int i = 0; i < verts.size(); i++) {
        V v1 = verts.get(i);
        for (int j = i + 1; j < verts.size(); j++) {
            V v2 = verts.get(j);
            if (!target.containsEdge(v1, v2)) {
                target.addEdge(v1, v2);
            }
        }
    }
}

