public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Compute the size of the serialized message
    int size = schema.getSerializedSize(message, buffer);
    // Write the size as a varint to the output stream
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeUInt32NoTag(size);
    // Write the actual message contents
    schema.writeTo(cos, message);
    // Flush the CodedOutputStream to ensure all bytes are written
    cos.flush();
    // Return the size of the message (excluding the size prefix)
    return size;
}

int function ( OutputStream out , T message , Schema<T> schema , LinkedBuffer buffer ) throws IOException {
    int size = schema.getSerializedSize(message);
    out.write((size >>> 24) & 0xFF);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    schema.writeTo(message, out, buffer);
    return size;
}

int function ( OutputStream arg0 , T arg1 , Schema<T> arg2 , LinkedBuffer arg3 ) throws IOException {
    int size = arg2.getSerializedSize(arg1);
    CodedOutputStream cos = CodedOutputStream.newInstance(arg0);
    cos.writeRawVarint32(size);
    arg2.write(arg1, cos);
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute serialized size of the message
    int dataSize = schema.computeSize(message, buffer);
    // Write the size as a 4‑byte integer (big‑endian)
    byte[] len = ByteBuffer.allocate(4).putInt(dataSize).array();
    out.write(len);
    // Serialize the message itself
    schema.writeTo(out, message, buffer);
    out.flush();
    return dataSize;
}

