public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType paramType = (ParameterizedType) genericType;
    Type[] actualArgs = paramType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualArgs.length];

    // Build a map from TypeVariable to actual Type using targetType's hierarchy
    java.util.Map<TypeVariable<?>, Type> typeVarAssigns = new java.util.HashMap<>();
    java.util.Deque<Class<?>> stack = new java.util.ArrayDeque<>();
    stack.push(targetType);
    while (!stack.isEmpty()) {
        Class<?> clazz = stack.pop();
        // Superclass
        Type superType = clazz.getGenericSuperclass();
        if (superType instanceof ParameterizedType) {
            ParameterizedType pSuper = (ParameterizedType) superType;
            TypeVariable<?>[] vars = ((Class<?>) pSuper.getRawType()).getTypeParameters();
            Type[] args = pSuper.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                typeVarAssigns.put(vars[i], args[i]);
            }
            if (pSuper.getRawType() instanceof Class) {
                stack.push((Class<?>) pSuper.getRawType());
            }
        } else if (superType instanceof Class) {
            stack.push((Class<?>) superType);
        }
        // Interfaces
        for (Type itype : clazz.getGenericInterfaces()) {
            if (itype instanceof ParameterizedType) {
                ParameterizedType pIface = (ParameterizedType) itype;
                TypeVariable<?>[] vars = ((Class<?>) pIface.getRawType()).getTypeParameters();
                Type[] args = pIface.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    typeVarAssigns.put(vars[i], args[i]);
                }
                if (pIface.getRawType() instanceof Class) {
                    stack.push((Class<?>) pIface.getRawType());
                }
            } else if (itype instanceof Class) {
                stack.push((Class<?>) itype);
            }
        }
    }

    // Resolve each type argument
    for (int i = 0; i < actualArgs.length; i++) {
        Type t = actualArgs[i];
        Class<?> resolved = null;
        if (t instanceof Class) {
            resolved = (Class<?>) t;
        } else if (t instanceof TypeVariable) {
            Type mapped = typeVarAssigns.get(t);
            if (mapped instanceof Class) {
                resolved = (Class<?>) mapped;
            } else if (mapped instanceof ParameterizedType) {
                resolved = (Class<?>) ((ParameterizedType) mapped).getRawType();
            }
        } else if (t instanceof ParameterizedType) {
            resolved = (Class<?>) ((ParameterizedType) t).getRawType();
        }
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        // Not parameterized; cannot resolve arguments
        return null;
    }
    ParameterizedType paramType = (ParameterizedType) genericType;
    Type[] actualTypes = paramType.getActualTypeArguments();
    Class<?>[] resolved = new Class<?>[actualTypes.length];
    for (int i = 0; i < actualTypes.length; i++) {
        Type t = actualTypes[i];
        if (t instanceof Class<?>) {
            resolved[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) t).getRawType();
            if (raw instanceof Class<?>) {
                resolved[i] = (Class<?>) raw;
            } else {
                // Cannot resolve nested parameterization
                return null;
            }
        } else if (t instanceof TypeVariable<?>) {
            // Attempt to resolve using the provided targetType's type variable mapping
            // If targetType is null or mapping fails, return null
            if (targetType == null) {
                return null;
            }
            // Build a mapping from the target type's type parameters to actual classes
            // based on the inheritance chain.
            // This is a simplified approach and may not cover all cases.
            Map<TypeVariable<?>, Type> targetMap = new HashMap<>();
            Class<?> current = targetType;
            while (current != null) {
                TypeVariable<?>[] params = current.getTypeParameters();
                Type superType = current.getGenericSuperclass();
                if (superType instanceof ParameterizedType) {
                    ParameterizedType superParam = (ParameterizedType) superType;
                    Type[] superArgs = superParam.getActualTypeArguments();
                    for (int j = 0; j < params.length; j++) {
                        targetMap.put(params[j], superArgs[j]);
                    }
                }
                current = current.getSuperclass();
            }
            Type resolvedType = targetMap.get(t);
            if (resolvedType instanceof Class<?>) {
                resolved[i] = (Class<?>) resolvedType;
            } else {
                return null;
            }
        } else {
            // Unsupported type, cannot resolve
            return null;
        }
    }
    return resolved;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType paramType = (ParameterizedType) genericType;
    Type rawType = paramType.getRawType();
    if (!(rawType instanceof Class)) {
        return null;
    }
    // Find the ParameterizedType in targetType's hierarchy that matches rawType
    ParameterizedType targetParam = findMatchingParameterizedSuperType(targetType, (Class<?>) rawType);
    if (targetParam == null) {
        return null;
    }
    // Build a map from type variables to actual types defined in the target hierarchy
    TypeVariable<?>[] typeParams = ((Class<?>) rawType).getTypeParameters();
    Type[] actualArgs = targetParam.getActualTypeArguments();
    if (actualArgs.length != typeParams.length) {
        return null;
    }
    Map<TypeVariable<?>, Type> map = new HashMap<>();
    for (int i = 0; i < typeParams.length; i++) {
        map.put(typeParams[i], actualArgs[i]);
    }
    // Resolve each argument of genericType using the map
    Type[] genericArgs = paramType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[genericArgs.length];
    for (int i = 0; i < genericArgs.length; i++) {
        Class<?> resolved = resolveTypeToClass(genericArgs[i], map);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

