public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the history mapping for the given table. The exact implementation depends
    // on how mappings are stored; here we assume there is a helper method getHistoryMapping.
    Mappings historic = getHistoryMapping(tableName);
    // Prepare the diff mapping that will hold fields missing from the input mappings.
    Mappings diff = new Mappings();

    // Assume Mappings exposes a map of field names to field definitions.
    Map<String, Object> historicFields = historic.getFields(); // history mapping fields
    Map<String, Object> currentFields = mappings.getFields(); // current input mapping fields

    for (Map.Entry<String, Object> entry : historicFields.entrySet()) {
        String field = entry.getKey();
        // Skip the special _source field to avoid update conflict.
        if ("_source".equals(field)) {
            continue;
        }
        // If the field is missing from the current mapping, add it to the diff.
        if (!currentFields.containsKey(field)) {
            diff.putField(field, entry.getValue());
        }
    }

    return diff;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings current = getCurrentIndexMapping(tableName);
    Mappings diff = new Mappings();
    if (current == null) {
        return diff;
    }
    for (String field : current.getFieldNames()) {
        if ("_source".equals(field)) {
            continue;
        }
        if (!mappings.hasField(field)) {
            diff.setField(field, current.getField(field));
        }
    }
    return diff;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Obtain the current mapping for the specified table from the index
    Mappings currentMapping = fetchCurrentMapping(tableName);
    if (currentMapping == null) {
        // If the current mapping cannot be retrieved, return an empty mapping
        return new Mappings();
    }

    Map<String, Object> currentProps = currentMapping.getProperties();
    Map<String, Object> inputProps  = mappings.getProperties();

    Map<String, Object> diffProps = new HashMap<>();
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String fieldName = entry.getKey();

        // Skip the "_source" field to avoid current index update conflict
        if ("_source".equals(fieldName)) {
            continue;
        }

        // If the field is not present in the provided mappings, include it in the diff
        if (!inputProps.containsKey(fieldName)) {
            diffProps.put(fieldName, entry.getValue());
        }
    }

    Mappings diffMappings = new Mappings();
    diffMappings.setProperties(diffProps);
    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the historical mapping snapshot for the table
    Mappings history = getHistoryMapping(tableName);
    if (history == null) {
        return new Mappings(); // no history, nothing to diff
    }

    Map<String, Object> historyProps = history.getProperties();
    Map<String, Object> diffProps = new HashMap<>();

    for (Map.Entry<String, Object> entry : historyProps.entrySet()) {
        String fieldName = entry.getKey();
        // Skip the _source field to avoid update conflicts
        if ("_source".equals(fieldName)) {
            continue;
        }
        // Include only those fields that are missing in the supplied mapping
        if (!mappings.containsField(fieldName)) {
            diffProps.put(fieldName, entry.getValue());
        }
    }

    return new Mappings(diffProps);
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    /* Fetch the most recent index mapping for the given table.  */
    Mappings current = IndexManager.getMapping(tableName); // may return null

    if (current == null) {
        return new Mappings(); // nothing to diff
    }

    /* Build a new mapping that contains only the fields that do not exist
       in the supplied (history) mapping.  */
    Mappings diff = new Mappings();

    for (String fieldName : current.getFieldNames()) {
        if (!mappings.containsField(fieldName)) {
            diff.addField(fieldName, current.getField(fieldName));
        }
    }

    return diff;
}

