    if (str == null || len <= 0) {
        return 0;
    }
    int size = 0;
    int end = index + len;
    for (int pos = index; pos < end; ) {
        char c = str.charAt(pos);
        int cp;
        if (Character.isHighSurrogate(c) && pos + 1 < end) {
            char c2 = str.charAt(pos + 1);
            if (Character.isLowSurrogate(c2)) {
                cp = Character.toCodePoint(c, c2);
                pos += 2;
            } else {
                cp = c;
                pos++;
            }
        } else {
            cp = c;
            pos++;
        }
        if (cp <= 0x7F) {
            size++;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

