public boolean remove(int val){
    // Iterate over the current size of the set
    for (int i = 0; i < size; i++) {
        // If the element matches the value to remove
        if (items[i] == val) {
            // Shift subsequent elements left to fill the gap
            for (int j = i; j < size - 1; j++) {
                items[j] = items[j + 1];
            }
            // Decrease the logical size of the set
            size--;
            // Return true to indicate a successful removal
            return true;
        }
    }
    // Value was not found; return false
    return false;
}

