    // Unlink this edge from the doubly linked list of edges on the source node
    if (prevSource != null) {
        prevSource.nextSource = nextSource;
    }
    if (nextSource != null) {
        nextSource.prevSource = prevSource;
    }

    // Unlink this edge from the doubly linked list of edges on the target node
    if (prevTarget != null) {
        prevTarget.nextTarget = nextTarget;
    }
    if (nextTarget != null) {
        nextTarget.prevTarget = prevTarget;
    }

