        return result;
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    java.lang.String[] parts = path.split("/", -1);
    for (java.lang.String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        if (decode) {
            try {
                part = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.lang.Exception ignored) {
            }
        }
        result.add(new PathSegmentImpl(part));
    }
    return result;
}

