public Converter lookup(final Class<?> clazz){
    if (clazz == null) {
        return null;
    }
    Converter converter = converterMap.get(clazz);
    if (converter != null) {
        return converter;
    }
    // Search interfaces
    for (Class<?> iface : clazz.getInterfaces()) {
        converter = converterMap.get(iface);
        if (converter != null) {
            return converter;
        }
    }
    // Search superclass chain
    Class<?> superCls = clazz.getSuperclass();
    while (superCls != null) {
        converter = converterMap.get(superCls);
        if (converter != null) {
            return converter;
        }
        superCls = superCls.getSuperclass();
    }
    return null;
}

