    int len = descriptor.length();
    int pos = 0;
    // If this is a method descriptor, ignore the return type
    if (descriptor.charAt(0) == '(') {
        pos++; // skip '('
        while (pos < len && descriptor.charAt(pos) != ')') {
            pos = consumeType(descriptor, pos);
        }
    } else {
        while (pos < len) {
            pos = consumeType(descriptor, pos);
        }
    }
