private void pop(final String descriptor) {
    int i = 0;
    final int len = descriptor.length();
    if (len == 0) {
        return;
    }
    // Skip argument list for method descriptors
    if (descriptor.charAt(0) == '(') {
        int close = descriptor.indexOf(')');
        if (close < 0) { // malformed descriptor
            return;
        }
        i = close + 1;
    }

    while (i < len) {
        char c = descriptor.charAt(i);
        switch (c) {
            // Primitive types that occupy a single slot
            case 'B': case 'C': case 'I':
            case 'S': case 'Z':
                stack.pop();
                i++;
                break;

            // Primitive types that occupy a single slot (float)
            case 'F':
                stack.pop();
                i++;
                break;

            // Primitive types that occupy two slots
            case 'J': case 'D':
                stack.pop();
                stack.pop();
                i++;
                break;

            // Object references
            case 'L':
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon < 0) {
                    return; // malformed descriptor
                }
                i = semicolon + 1;
                stack.pop();
                break;

            // Array types
            case '[':
                // Consume all array brackets
                do {
                    i++;
                } while (i < len && descriptor.charAt(i) == '[');

                if (i < len && descriptor.charAt(i) == 'L') {
                    int end = descriptor.indexOf(';', i);
                    if (end < 0) {
                        return; // malformed descriptor
                    }
                    i = end + 1;
                } else {
                    i++; // primitive component
                }
                stack.pop();
                break;

            // Anything else is unexpected; just advance to avoid infinite loop
            default:
                i++;
                break;
        }
    }
}

