private void pop(final String descriptor){
    int idx = 0;
    int len = descriptor.length();
    // Case 1: method descriptor
    if (idx < len && descriptor.charAt(idx) == '('){
        idx++; // skip '('
        while (idx < len && descriptor.charAt(idx) != ')'){
            // consume one argument descriptor
            char c = descriptor.charAt(idx);
            if (c == '['){
                // array type – consume all leading '['
                while (idx < len && descriptor.charAt(idx) == '['){
                    idx++;
                }
                // the element type
                if (idx < len && descriptor.charAt(idx) == 'L'){
                    idx++; // skip 'L'
                    while (idx < len && descriptor.charAt(idx) != ';'){
                        idx++;
                    }
                    idx++; // skip ';'
                }else{
                    // primitive array element
                    idx++; // single primitive descriptor
                }
            }else if (c == 'L'){
                // object type
                idx++; // skip 'L'
                while (idx < len && descriptor.charAt(idx) != ';'){
                    idx++;
                }
                idx++; // skip ';'
            }else{
                // primitive type – single char
                idx++;
            }
            // pop the corresponding abstract type from the stack
            outputFrameStack.pop();
        }
    }else{
        // Case 2: single type descriptor (non-method)
        if (idx < len){
            char c = descriptor.charAt(idx);
            if (c == '['){
                while (idx < len && descriptor.charAt(idx) == '['){
                    idx++;
                }
                if (idx < len && descriptor.charAt(idx) == 'L'){
                    idx++;
                    while (idx < len && descriptor.charAt(idx) != ';'){
                        idx++;
                    }
                    idx++; // skip ';'
                }else{
                    idx++; // primitive array element
                }
            }else if (c == 'L'){
                idx++;
                while (idx < len && descriptor.charAt(idx) != ';'){
                    idx++;
                }
                idx++; // skip ';'
            }else{
                idx++;
            }
            outputFrameStack.pop();
        }
    }
}

