    if (!Character.class.isAssignableFrom(type) && !Character.TYPE.equals(type)) {
        throw new IllegalArgumentException("Unsupported target type for conversion: " + type.getName());
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = ((String) value).trim();
        if (s.length() != 1) {
            throw new Exception("Cannot convert string to Character: length is not 1");
        }
        return Character.valueOf(s.charAt(0));
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

