        if (n <= 0) return Integer.MAX_VALUE; // overflow guard
        int limit = (int)Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                n += 2;
                continue outer;
            }
        }
        return n;
    }
