final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // Assumes classFileBuffer is a byte array containing the class file bytes
    // and that constantPoolEntryIndex is 1‑based.
    // Locate the start of the constant pool.
    int offset = 10; // 4 (magic) +2 (minor_version) +2 (major_version) +2 (constant_pool_count)
    // Skip over entries up to the desired index
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[offset++] & 0xFF;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
                offset += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                i++; // These take up two entries in the table
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
                offset += 2;
                break;
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
                offset += 4;
                break;
            case 15: // CONSTANT_MethodHandle
                offset += 3;
                break;
            case 16: // CONSTANT_MethodType
                offset += 2;
                break;
            case 18: // CONSTANT_InvokeDynamic
                offset += 4;
                break;
            default:
                // Unknown tag – stop parsing this entry
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
    }
    // Now read the desired CONSTANT_Utf8 entry
    int tag = classFileBuffer[offset++] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex + ", found tag " + tag);
    }
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    // Ensure charBuffer is large enough
    if (charBuffer == null || charBuffer.length < length) {
        throw new IllegalArgumentException("Provided charBuffer is null or too small");
    }
    // Copy bytes into a new byte array to construct the String
    byte[] utfBytes = new byte[length];
    System.arraycopy(classFileBuffer, offset, utfBytes, 0, length);
    String result = new String(utfBytes, java.nio.charset.StandardCharsets.UTF_8);
    // Optionally copy the resulting characters into the provided buffer
    result.getChars(0, length, charBuffer, 0);
    return result;
}

