    try {
        // Find the byte offset of the CONSTANT_Utf8 entry in the class file buffer
        int entryOffset = getConstantPoolEntryOffset(constantPoolEntryIndex);
        // Skip the tag byte (1 byte) and read the length (2 bytes, big-endian)
        int length = classFileBuffer.getShort(entryOffset + 1) & 0xFFFF;
        byte[] bytes = new byte[length];
        classFileBuffer.position(entryOffset + 3);
        classFileBuffer.get(bytes, 0, length);
        // Convert the bytes to a UTF-8 string
        String result = new String(bytes, "UTF-8");
        // If a char buffer is supplied, copy the string contents into it
        if (charBuffer != null) {
            int copyLen = Math.min(result.length(), charBuffer.length);
            result.getChars(0, copyLen, charBuffer, 0);
        }
        return result;
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

