    byte tag = classFileBuffer.get();
    if (tag != 1) {
        throw new IllegalArgumentException(
                "Expected CONSTANT_Utf8 tag at index " + constantPoolEntryIndex);
    }

    // Read the length of the UTF‑8 string (unsigned short)
    int length = classFileBuffer.getShort() & 0xFFFF;

    // Validate the provided buffer is large enough
    if (charBuffer.length < length) {
        throw new IllegalArgumentException(
                "Provided char buffer too small (required " + length + ", available "
                        + charBuffer.length + ")");
    }

    // Read the bytes of the string
    byte[] bytes = new byte[length];
    classFileBuffer.get(bytes, 0, length);

    // Convert to String using UTF‑8
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

