protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) return null;
    List<E> pathEdges = new ArrayList<>(tour);
    return new GraphPath<>(graph, pathEdges);
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Convert the Set of edges into a list to preserve iteration order
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    if (!edgeList.isEmpty()) {
        // Start from an arbitrary edge
        E firstEdge = edgeList.get(0);
        V src = graph.getEdgeSource(firstEdge);
        V tgt = graph.getEdgeTarget(firstEdge);
        vertexList.add(src);
        vertexList.add(tgt);

        Set<E> visited = new HashSet<>();
        visited.add(firstEdge);
        V current = tgt;

        // Walk through edges to build a continuous path
        while (visited.size() < edgeList.size()) {
            boolean foundNext = false;
            for (E e : edgeList) {
                if (visited.contains(e)) continue;
                V source = graph.getEdgeSource(e);
                V target = graph.getEdgeTarget(e);
                if (source.equals(current)) {
                    vertexList.add(target);
                    current = target;
                    visited.add(e);
                    foundNext = true;
                    break;
                } else if (target.equals(current)) {
                    vertexList.add(source);
                    current = source;
                    visited.add(e);
                    foundNext = true;
                    break;
                }
            }
            if (!foundNext) {
                // Cannot continue due to a disconnected set of edges
                break;
            }
        }
    }

    // Compute total weight of the path
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }

    // Construct the GraphPath
    return new org.jgrapht.graph.DefaultGraphPath<>(vertexList, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    List<E> edgeSequence = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);

    // Build adjacency list: edge source to edges
    Map<V, List<E>> outgoing = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        outgoing.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        outgoing.computeIfAbsent(tgt, k -> new ArrayList<>()); // ensure vertex entry
    }

    V current = graph.getEdgeSource(tour.iterator().next());
    while (!remaining.isEmpty()) {
        List<E> edgesFromCur = outgoing.get(current);
        if (edgesFromCur == null) {
            break;
        }
        E next = null;
        for (E e : edgesFromCur) {
            if (remaining.contains(e)) {
                next = e;
                break;
            }
        }
        if (next == null) {
            break;
        }
        edgeSequence.add(next);
        remaining.remove(next);
        current = graph.getEdgeTarget(next);
    }

    if (edgeSequence.isEmpty()) {
        return null;
    }

    List<V> vertexSequence = new ArrayList<>();
    V startVertex = graph.getEdgeSource(edgeSequence.get(0));
    vertexSequence.add(startVertex);
    for (E e : edgeSequence) {
        vertexSequence.add(graph.getEdgeTarget(e));
    }

    double weight = 0;
    for (E e : edgeSequence) {
        weight += graph.getEdgeWeight(e);
    }

    return new GraphPathImpl<>(graph, vertexSequence, edgeSequence, weight);
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException();
    }
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    if (edgeList.isEmpty()) {
        return new DefaultGraphPath<>(graph, vertexList, Collections.emptyList(), 0);
    }
    V start = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(start);
    V current = start;
    Set<E> remaining = new HashSet<>(edgeList);
    while (!remaining.isEmpty()) {
        boolean moved = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V u = graph.getEdgeSource(e);
            V v = graph.getEdgeTarget(e);
            if (u.equals(current)) {
                vertexList.add(v);
                current = v;
                it.remove();
                moved = true;
                break;
            } else if (v.equals(current)) {
                vertexList.add(u);
                current = u;
                it.remove();
                moved = true;
                break;
            }
        }
        if (!moved) {
            break;
        }
    }
    double weight = tour.stream().mapToDouble(e -> graph.getEdgeWeight(e)).sum();
    return new DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) return null;
    List<E> edgeList = new ArrayList<>(tour);
    E firstEdge = edgeList.get(0);
    V start = graph.getEdgeSource(firstEdge);
    E lastEdge = edgeList.get(edgeList.size() - 1);
    V end = graph.getEdgeTarget(lastEdge);
    return new DefaultGraphPath<>(graph, start, end, edgeList, 0.0d);
}

