int addConstantNameAndType(final String name, final String descriptor) {
    // Construct a key that uniquely identifies the NameAndType entry
    NameAndTypeKey key = new NameAndTypeKey(name, descriptor);
    // Check if the constant pool already contains an entry with the same key
    Integer existingIndex = nameAndTypeIndexMap.get(key);
    if (existingIndex != null) {
        // Return the existing index if found
        return existingIndex;
    }
    // Create a new constant pool entry
    int newIndex = constantPool.size();
    constantPool.add(new NameAndTypeInfo(name, descriptor));
    // Record the new index in the lookup map
    nameAndTypeIndexMap.put(key, newIndex);
    // Return the newly added index
    return newIndex;
}

int addConstantNameAndType(final String name, final String descriptor) {
    // Search for an existing CONSTANT_NameAndType_info entry
    int existingIndex = constantPool.indexOfNameAndType(name, descriptor);
    if (existingIndex >= 0) {
        return existingIndex;
    }

    // Add the name and descriptor as UTF-8 constants first
    int nameIndex = constantPool.addUtf8(name);
    int descriptorIndex = constantPool.addUtf8(descriptor);

    // Create the new CONSTANT_NameAndType_info and add it to the pool
    int nameAndTypeIndex = constantPool.addNameAndType(nameIndex, descriptorIndex);

    return nameAndTypeIndex;
}

int addConstantNameAndType(final String name, final String descriptor) {
    // Use a composite key to uniquely identify a name/descriptor pair
    String key = name + '\u0000' + descriptor;
    // Check if an entry already exists
    Integer existingIndex = nameAndTypeIndex.get(key);
    if (existingIndex != null) {
        return existingIndex;
    }
    // Create a new constant pool entry for the name and type
    ConstantNameAndTypeInfo newEntry = new ConstantNameAndTypeInfo(name, descriptor);
    // The index is the current size before adding
    int newIndex = constantPool.size();
    // Add the entry to the constant pool
    constantPool.add(newEntry);
    // Map the composite key to the new index for future lookups
    nameAndTypeIndex.put(key, newIndex);
    return newIndex;
}

int addConstantNameAndType(final String name,final String descriptor){
    String key = name + ":" + descriptor;
    Integer index = nameAndTypeMap.get(key);
    if (index != null) {
        return index;
    }
    CONSTANT_NameAndType_info entry = new CONSTANT_NameAndType_info(name, descriptor);
    int newIndex = constantPool.size();
    constantPool.add(entry);
    nameAndTypeMap.put(key, newIndex);
    return newIndex;
}

int addConstantNameAndType(final String name,final String descriptor){
    int nameIdx = addConstantUtf8(name);
    int descriptorIdx = addConstantUtf8(descriptor);
    for (int i = 0; i < getConstantPoolSize(); i++) {
        ConstantPoolInfo entry = getConstantInfo(i);
        if (entry instanceof CONSTANT_NameAndType_info) {
            CONSTANT_NameAndType_info nt = (CONSTANT_NameAndType_info) entry;
            if (nt.getNameIndex() == nameIdx && nt.getDescriptorIndex() == descriptorIdx) {
                return i;
            }
        }
    }
    CONSTANT_NameAndType_info ntInfo = new CONSTANT_NameAndType_info(nameIdx, descriptorIdx);
    int idx = addConstantInfo(ntInfo);
    return idx;
}

private String unescapeId(String input){
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                sb.append(input.charAt(i + 1));
                i++;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(++i);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case 'x':
                    if (i + 2 < input.length()) {
                        String hex = input.substring(i + 1, i + 3);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                        } catch (NumberFormatException e) {
                            // ignore malformed hex escape
                        }
                        i += 2;
                    }
                    break;
                default:
                    sb.append(next);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // Remove backslash escapes: \x -> x
    return input.replaceAll("\\\\(.)", "$1");
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    boolean escaped = false;
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (escaped) {
            sb.append(c);
            escaped = false;
        } else {
            if (c == '\\') {
                escaped = true;
            } else {
                sb.append(c);
            }
        }
    }
    return sb.toString();
}

