private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    if (bucketsByLabel == null || labels == null || minLabel < 0) {
        return;
    }
    if (minLabel >= bucketsByLabel.size()) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    // Ensure bucket 0 exists
    Set<Integer> target = (bucketsByLabel.size() > 0) ? bucketsByLabel.get(0) : null;
    if (target == null) {
        target = new HashSet<>();
        if (bucketsByLabel.size() == 0) {
            bucketsByLabel.add(target);
        } else {
            bucketsByLabel.set(0, target);
        }
    }
    for (Integer vertex : source) {
        target.add(vertex);
        if (vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
    }
    source.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel < 0 || minLabel >= bucketsByLabel.size() || minLabel == 0) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new HashSet<>();
        // Ensure the list has space for index 0
        while (bucketsByLabel.size() <= 0) {
            bucketsByLabel.add(new HashSet<>());
        }
        bucketsByLabel.set(0, target);
    }
    for (Integer vertex : source) {
        target.add(vertex);
        if (vertex < labels.size()) {
            labels.set(vertex, 0);
        }
    }
    source.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()){
        return;
    }
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()){
        return;
    }
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null){
        zeroBucket = new java.util.HashSet<>();
        // ensure list has element at index 0
        if (bucketsByLabel.size() == 0){
            bucketsByLabel.add(zeroBucket);
        } else {
            bucketsByLabel.set(0, zeroBucket);
        }
    }
    for (int vertex : minBucket){
        zeroBucket.add(vertex);
        if (vertex >= 0 && vertex < labels.size()){
            labels.set(vertex, 0);
        }
    }
    minBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    for (Integer v : new HashSet<>(minBucket)) {
        labels.set(v, 0);
        zeroBucket.add(v);
    }
    minBucket.clear();
}

