private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffix = new ArrayList<>(bounds.size());
    // initialize with zeros
    for (int i = 0; i < bounds.size(); i++) {
        suffix.add(0);
    }
    long totalSum = 0;
    for (Integer val : bounds) {
        totalSum += val;
    }
    long cur = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        cur += bounds.get(i);
        suffix.set(i, (int)cur);
    }
    return Pair.of(suffix, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    int n = bounds.size();
    int[] suffixArray = new int[n];
    long total = 0;
    for (int i = n - 1; i >= 0; i--) {
        total += bounds.get(i);
        suffixArray[i] = (int) total;
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int value : suffixArray) {
        suffixList.add(value);
    }
