    for (int i = n - 1; i >= 0; i--) {
        temp[i] = temp[i + 1] + bounds.get(i);
    }
    long totalSum = 0;
    for (int i = 0; i < n; i++) {
        suffix.add((int) temp[i]);
        totalSum += bounds.get(i);
    }
