    for (java.util.Map.Entry<String,Object> entry : map.entrySet()) {
        String property = entry.getKey();
        Object value = entry.getValue();
        try {
            java.beans.PropertyDescriptor srcPd = new java.beans.PropertyDescriptor(property, map.getBean().getClass());
            if (srcPd.getReadMethod() == null) {
                continue; // source is write‑only
            }
            java.beans.PropertyDescriptor dstPd = new java.beans.PropertyDescriptor(property, this.getBean().getClass());
            if (dstPd.getWriteMethod() == null) {
                continue; // target is read‑only
            }
            this.put(property, value);
        } catch (java.beans.IntrospectionException e) {
            // ignore properties that cannot be introspected
        }
    }
}

