public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Assumes a field 'name' containing the full string to abbreviate
    if (name == null) {
        return;
    }
    if (nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    String rest = name.substring(nameStart);
    String[] parts = rest.split("\\.");
    for (String part : parts) {
        if (!part.isEmpty()) {
            buf.append(part.charAt(0)).append('.');
        }
    }
    int len = buf.length();
    if (len > 0 && buf.charAt(len - 1) == '.') {
        buf.setLength(len - 1);
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    // Ensure the name start index is valid
    if (nameStart < 0 || name == null || nameStart >= name.length()){
        return;
    }
    boolean first = true;
    char prev = 0;
    for (int i = nameStart; i < name.length(); i++){
        char c = name.charAt(i);
        // Append the character if it is the first character,
        // or it is an uppercase letter, or it follows a non‑alphanumeric
        // character (word boundary). Lowercase the appended letter for
        // consistency with typical abbreviation conventions.
        if (first || Character.isUpperCase(c) || !Character.isLetterOrDigit(prev)){
            buf.append(Character.toLowerCase(c));
            first = false;
        }
        prev = c;
    }
}

