public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        return;
    }
    int len = buf.length();
    if (nameStart >= len) {
        return;
    }
    // Preserve the prefix before nameStart
    StringBuffer result = new StringBuffer();
    result.append(buf.substring(0, nameStart));

    int pos = nameStart;
    while (pos < len) {
        int nextDot = buf.indexOf(".", pos);
        int partEnd = (nextDot == -1) ? len : nextDot;
        // Append the first character of the current part if it exists
        if (pos < partEnd) {
            result.append(buf.charAt(pos));
        }
        // If there is a dot, add it as separator
        if (nextDot == -1) {
            break;
        }
        result.append('.');
        pos = nextDot + 1;
    }
    // Replace original buffer content with the abbreviated form
    buf.setLength(0);
    buf.append(result);
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        return;
    }
    // Take the current buffer contents as the full name string.
    String fullName = buf.toString();
    if (nameStart < 0 || nameStart >= fullName.length()) {
        return;
    }
    // Extract the substring that will be abbreviated.
    String part = fullName.substring(nameStart);
    // Split the substring into words using '.' as a delimiter.
    String[] tokens = part.split("\\.");
    // Build the abbreviation by taking the first character of each token.
    StringBuilder abbrev = new StringBuilder();
    for (String token : tokens) {
        if (!token.isEmpty()) {
            abbrev.append(token.charAt(0));
            abbrev.append('.');
        }
    }
    // Remove the trailing dot if there was any abbreviation added.
    if (abbrev.length() > 0) {
        abbrev.setLength(abbrev.length() - 1);
    }
    // Append the abbreviation to the original buffer.
    buf.append(abbrev.toString());
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds != null && bounds.length > 0 && bounds[0] != null) {
        return bounds[0];
    }
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    for (Type bound : typeVariable.getBounds()) {
        if (bound instanceof Class<?>) {
            return bound;
        }
        if (bound instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) bound).getRawType();
            if (raw instanceof Class<?>) {
                return raw;
            }
        }
        if (bound instanceof WildcardType) {
            WildcardType wt = (WildcardType) bound;
            Type[] upper = wt.getUpperBounds();
            if (upper.length > 0 && upper[0] instanceof Class<?>) {
                return upper[0];
            }
        }
    }
    return Unknown.class;
}

