private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // A subgraph with 0 or 1 vertices is vacuously a clique
    if (vertices.size() <= 1) {
        return true;
    }

    // Iterate over all unordered pairs of vertices
    for (V v : vertices) {
        for (V u : vertices) {
            if (v.equals(u)) {
                continue;
            }
            // For undirected graphs, containsEdge(v, u) should be true
            if (!graph.containsEdge(v, u)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    int size = vertices.size();
    if (size <= 1) return true;
    java.util.List<V> list = new java.util.ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V u = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V v = list.get(j);
            if (!graph.containsEdge(u, v)) return false;
        }
    }
    return true;
}

