    }
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort((o1, o2) -> {
        if (o1 instanceof Comparable && o2 instanceof Comparable) {
            return ((Comparable) o1).compareTo(o2);
        }
        return 0;
    });
    for (K key : keys) {
        Integer bound = null;
        for (K candidate : sorted) {
            if (candidate instanceof Comparable && key instanceof Comparable) {
                int cmp = ((Comparable) candidate).compareTo(key);
                if (cmp <= 0) {
                    bound = candidate instanceof Number ? ((Number) candidate).intValue() : 0;
                }
            }
        }
        lowerBounds.add(bound);
    }
    return lowerBounds;
}

