private void pop(final String descriptor) {
    int slotsToPop = 0;
    int i = 0;
    if (descriptor.startsWith("(")) {
        // method descriptor: parse argument types up to ')'
        i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            switch (c) {
                case 'L': {
                    // reference type, consume until ';'
                    i = descriptor.indexOf(';', i) + 1;
                    slotsToPop += 1;
                    break;
                }
                case '[': {
                    // array type
                    i++; // consume '['
                    // consume any further '[' (for multi-dimensional)
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                        i++;
                    }
                    if (i < descriptor.length() && descriptor.charAt(i) == 'L') {
                        i = descriptor.indexOf(';', i) + 1;
                    } else {
                        // primitive component type
                        i++;
                    }
                    slotsToPop += 1;
                    break;
                }
                case 'J':
                case 'D': {
                    // long or double occupy two slots
                    i++;
                    slotsToPop += 2;
                    break;
                }
                default: {
                    // all other primitive types occupy one slot
                    i++;
                    slotsToPop += 1;
                    break;
                }
            }
        }
    } else {
        // single type descriptor
        char c = descriptor.charAt(0);
        switch (c) {
            case 'L':
            case '[':
                slotsToPop = 1;
                break;
            case 'J':
            case 'D':
                slotsToPop = 2;
                break;
            default:
                slotsToPop = 1;
                break;
        }
    }
    // Pop the calculated number of slots from the output frame stack
    for (int j = 0; j < slotsToPop; j++) {
        outputFrameStack.pop(); // assumes outputFrameStack is a field of type Deque or Stack
    }
}

