    int slots = 0;
    if (descriptor.startsWith("(")){
        int i = 1;
        // parse argument descriptors
        while (i < descriptor.length() && descriptor.charAt(i) != ')'){
            char c = descriptor.charAt(i);
            if (c == 'L'){
                // object type: find ';'
                i = descriptor.indexOf(';', i) + 1;
                slots++;
            }else if (c == '['){
                // array type
                i++;
                // skip any nested array brackets
                while (i < descriptor.length() && descriptor.charAt(i) == '['){
                    i++;
                }
                if (i < descriptor.length() && descriptor.charAt(i) == 'L'){
                    // object in array: skip until ';'
                    i = descriptor.indexOf(';', i) + 1;
                }else{
                    // primitive array: just one slot, skip its type
                    i++;
                }
                slots++;
            }else{
                // primitive
                if (c == 'J' || c == 'D'){
                    slots += 2; // long and double take two slots
                }else{
                    slots += 1;
                }
                i++;
            }
        }
    }else{
        // single type descriptor
        char c = descriptor.charAt(0);
        if (c == 'L' || c == '['){
            slots = 1;
        }else{
            if (c == 'J' || c == 'D'){
                slots = 2;
            }else{
                slots = 1;
            }
        }
    }
    // pop stack slots
    for (int s = 0; s < slots; s++){
        outputStack.pop();
    }
