public static boolean equals(Point2D p1, Point2D p2) {
    if (p1 == null && p2 == null) {
        return true;
    }
    if (p1 == null || p2 == null) {
        return false;
    }
    double tol = 1e-9;
    return Math.abs(p1.getX() - p2.getX()) <= tol
            && Math.abs(p1.getY() - p2.getY()) <= tol;
}

