public static String applyRelativePath(String path, String relativePath){
    java.nio.file.Path base = java.nio.file.Paths.get(path).getParent();
    if (base == null){
        base = java.nio.file.Paths.get("");
    }
    java.nio.file.Path result = base.resolve(relativePath).normalize();
    return result.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if (path == null) return relativePath;
    if (relativePath == null) return path;
    List<String> parts = new ArrayList<>();
    for (String p : path.split("/")) {
        if (p.length() > 0) parts.add(p);
    }
    for (String r : relativePath.split("/")) {
        if (r.length() == 0 || r.equals(".")) {
            continue;
        } else if (r.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            }
        } else {
            parts.add(r);
        }
    }
