        String separator = "/";
        StringBuilder result = new StringBuilder();
        String[] baseParts = path.split(separator);
        String[] relParts = relativePath.split(separator);
        for (String part : baseParts) {
            if (!part.isEmpty()) {
                result.append(part).append(separator);
