        }
        for (String part : relParts) {
            if (part.equals("..")) {
                int lastSep = result.lastIndexOf(separator);
                if (lastSep != -1) {
                    result.setLength(lastSep);
                }
            } else if (!part.isEmpty() && !part.equals(".")) {
                result.append(part).append(separator);
            }
        }
