public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Determine the base directory of the given path.
    String dir = path;
    if (!dir.endsWith("/")) {
        int lastSlash = dir.lastIndexOf('/');
        if (lastSlash >= 0) {
            dir = dir.substring(0, lastSlash + 1);
        } else {
            dir = "";
        }
    }

    // Split the base directory into components and push onto a stack.
    java.util.List<String> stack = new java.util.ArrayList<>();
    if (!dir.isEmpty()) {
        String[] parts = dir.split("/");
        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1);
                }
            } else {
                stack.add(part);
            }
        }
    }

    // Apply each component of the relative path.
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Reconstruct the final path.
    StringBuilder result = new StringBuilder();
    if (path.startsWith("/")) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }

    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    if (path == null) {
        path = "";
    }
    // Ensure a separator between the base path and the relative path
    boolean pathEndsWithSlash = path.endsWith("/");
    String combined = pathEndsWithSlash ? path + relativePath : path + "/" + relativePath;

    // Split into components and resolve ".." and "." references
    String[] parts = combined.split("/");
    Deque<String> stack = new ArrayDeque<>();
    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (path.startsWith("/")) {
        result.append("/");
    }
    Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }
    return result.toString();
}

